#include "screens.h"
void render_keyboard(UiFramebuffer *f,App *a){const ModuleDescriptor *m=app_module(a,a->active_module);const char *title=a->keyboard_mode==KEYBOARD_URL?"Install module":a->keyboard_mode==KEYBOARD_FIELD?"Edit setting":m?m->name:"Search";render_header(f,title,a->keyboard_mode==KEYBOARD_URL?"HTTPS URL":"");const char *text=app_keyboard_text(a);size_t n=strlen(text);const char *visible=n>52?text+n-52:text;
    draw_round(f,UI_SAFE_X,UI_CONTENT_Y-5,UI_WIDTH-2*UI_SAFE_X,42,6,UI_PANEL,UI_PANEL);draw_text(f,UI_SAFE_X+14,UI_CONTENT_Y+5,*text?visible:"Type with your remote",20,*text?UI_INK:UI_MUTED,610);
    const char *letters=app_keyboard_letters(a);int cells=app_keyboard_cells(a),width=(UI_WIDTH-2*UI_SAFE_X)/10,start=UI_CONTENT_Y+54,height=42;
    for(int i=0;i<cells;i++){int x=UI_SAFE_X+(i%10)*width,y=start+(i/10)*height,focus=i==a->keyboard_focus;UiColor face=focus?UI_INK:UI_PANEL;draw_round(f,x+2,y,width-5,36,7,face,face);char letter[2]={(size_t)i<strlen(letters)?letters[i]:' ',0};draw_center(f,x+width/2,y+6,letter,20,focus?COLOR(18,18,22,255):UI_MUTED);}
    const char *labels[]={"Aa","Space","Delete","Clear",a->keyboard_mode==KEYBOARD_SEARCH?"Search":a->keyboard_mode==KEYBOARD_URL?"Install":"Save","Cancel"};const int col[]={0,1,2,3,4,8},span[]={1,1,1,1,4,2};for(int i=0;i<6;i++){int focus=i<4?a->keyboard_focus==cells+i:i==4?a->keyboard_focus>=cells+4&&a->keyboard_focus<=cells+7:a->keyboard_focus>=cells+8;render_button(f,UI_SAFE_X+col[i]*width+2,start+(cells/10)*height,span[i]*width-5,labels[i],focus);}render_footer(f,"Arrows  Move     SELECT  Type","BACK  Delete / Return");
}
